const t="zenkamoku-n1-best-workbook",e="w02-d04",n=2,b=4,c="第2週",i="4日目",r="言い換え類義 / 用法",u="Paraphrases / Usage",o=[{type:"paraphrases",title:"言い換え類義",titleEn:"Paraphrases",pageRef:"p.32",instruction:"＿＿＿の言葉に意味が最も近いものを、１・２・３・４から一つ選びなさい。",questions:[{number:1,stem:"どうせ授業に遅れるなら、<u>いっそ</u>休んでしまおう。",options:["1. やけに","2. すでに","3. とかく","4. むしろ"],correct:4,correctOption:"4. むしろ",explanation:"<b>【正解】4. むしろ</b><br/><b>いっそ</b>：思い切って rather; sooner"},{number:2,stem:"疲れからか、彼女につい<u>そっけない</u>態度をとってしまった。",options:["1. つれない","2. あどけない","3. ぎこちない","4. ふがいない"],correct:1,correctOption:"1. つれない",explanation:"<b>【正解】1. つれない</b><br/><b>そっけない</b>：思いやりや愛想がない cold; blunt"},{number:3,stem:"そんな<u>うやむやな</u>結論では困る。",options:["1. ややこしい","2. あいまいな","3. さえない","4. いい加減な"],correct:2,correctOption:"2. あいまいな",explanation:"<b>【正解】2. あいまいな</b><br/><b>うやむや(な)</b>：物事がはっきりしないまま終わる様子 undecided; vague"},{number:4,stem:"この戦争は<u>領土</u>の奪い合いから始まった。",options:["1. 地域","2. 一帯","3. 範囲","4. 国土"],correct:4,correctOption:"4. 国土",explanation:"<b>【正解】4. 国土</b><br/><b>領土</b>：国家が主権を行使できる区域 territory; domain"},{number:5,stem:"2階の床は<u>きしむ</u>ので、修理したほうがいい。",options:["1. 水漏れする","2. 音が鳴る","3. 腐っている","4. 壊れている"],correct:2,correctOption:"2. 音が鳴る",explanation:"<b>【正解】2. 音が鳴る</b><br/><b>きしむ</b>：物がこすれ合って音を立てる creak; squeak"},{number:6,stem:"彼には何事も<u>誇張して</u>話す癖がある。",options:["1. オーバーに","2. タフに","3. シンプルに","4. ユニークに"],correct:1,correctOption:"1. オーバーに",explanation:"<b>【正解】1. オーバーに</b><br/><b>誇張する</b>：大げさに表現すること exaggerate"}]},{type:"usage",title:"用法",titleEn:"Usage",pageRef:"pp.32-33",instruction:"次の言葉の使い方として最もよいものを、１・２・３・４から一つ選びなさい。",questions:[{number:1,stem:"行き詰まる",options:["1. 人間の成長は、遅くても20歳くらいで<u>行き詰まる</u>と言われている。","2. 人手不足と財政難で、経営に<u>行き詰まって</u>しまった。","3. 皆さんの協力のおかげで、最後まで<u>行き詰まる</u>ことができました。","4. 排水管にゴミが<u>行き詰まって</u>、水が流れにくくなっている。"],correct:2,correctOption:"2. 人手不足と財政難で、経営に<u>行き詰まって</u>しまった。",explanation:"<b>【正解】2. 人手不足と財政難で、経営に<u>行き詰まって</u>しまった。</b><br/><b><ruby>行<rt>い</rt></ruby>き<ruby>詰<rt>づ</rt></ruby>まる</b>：物事を解決するための手段が失われること come to a dead end"},{number:2,stem:"かろうじて",options:["1. 猛勉強したが、<u>かろうじて</u>不合格になってしまった。","2. <u>かろうじて</u>終電までには帰ってください。","3. あまりお金がありませんが、<u>かろうじて</u>車を買うつもりです。","4. 大事故にあったが、<u>かろうじて</u>命だけは助かった。"],correct:4,correctOption:"4. 大事故にあったが、<u>かろうじて</u>命だけは助かった。",explanation:"<b>【正解】4. 大事故にあったが、<u>かろうじて</u>命だけは助かった。</b><br/><b>かろうじて</b>：何とか方法を尽くして実現する様子 barely"},{number:3,stem:"うろたえる",options:["1. 少し運動しただけで<u>うろたえる</u>なんて、年を取ったな。","2. 彼女に浮気を追及されて、<u>うろたえて</u>しまった。","3. 公園に<u>うろたえた</u>人がいたので、警察に通報した。","4. 彼は思いがけないプレゼントに<u>うろたえて</u>喜んでいる。"],correct:2,correctOption:"2. 彼女に浮気を追及されて、<u>うろたえて</u>しまった。",explanation:"<b>【正解】2. 彼女に浮気を追及されて、<u>うろたえて</u>しまった。</b><br/><b>うろたえる</b>：思いがけないことに慌てて正常な判断ができなくなること be flustered"},{number:4,stem:"拍子",options:["1. 帰宅した<u>拍子</u>に電話がかかってきた。","2. 来年の3月を<u>拍子</u>に結婚するつもりだ。","3. 自転車をよけようとした<u>拍子</u>に、スマホを落としたようだ。","4. 暗い道で、<u>拍子</u>に背後から襲われる事件が多発している。"],correct:3,correctOption:"3. 自転車をよけようとした<u>拍子</u>に、スマホを落としたようだ。",explanation:"<b>【正解】3. 自転車をよけようとした<u>拍子</u>に、スマホを落としたようだ。</b><br/><b>～<ruby>拍<rt>ひょう</rt></ruby><ruby>子<rt>し</rt></ruby>に…</b>＝～をきっかけに…が起こる ～をしたちょうどその時に … in the instant that ～"},{number:5,stem:"精巧",options:["1. 先生から<u>精巧</u>にアドバイスをいただいたおかげで、試験に合格できました。","2. 事件があった日のことを<u>精巧</u>に話してください。","3. 提出する前に、論文の内容を<u>精巧</u>に確認する必要がある。","4. これは偽物だが、実に<u>精巧</u>に作られていて本物と見分けがつかない。"],correct:4,correctOption:"4. これは偽物だが、実に<u>精巧</u>に作られていて本物と見分けがつかない。",explanation:"<b>【正解】4. これは偽物だが、実に<u>精巧</u>に作られていて本物と見分けがつかない。</b><br/><b><ruby>精<rt>せい</rt></ruby><ruby>巧<rt>こう</rt></ruby>(な)</b>：細かいところまでよくできていること sophisticated; elaborate"},{number:6,stem:"ねばる",options:["1. 最後まで<u>ねばった</u>おかげで、勝利をつかむことができた。","2. 旧友と久しぶりに会い、話が<u>ねばって</u>終電を逃してしまった。","3. この薬は、朝飲むだけで夜までその効果が<u>ねばります</u>。","4. 昨日の疲れが<u>ねばり</u>、今朝はなかなか起きることができなかった。"],correct:1,correctOption:"1. 最後まで<u>ねばった</u>おかげで、勝利をつかむことができた。",explanation:"<b>【正解】1. 最後まで<u>ねばった</u>おかげで、勝利をつかむことができた。</b><br/><b>ねばる</b>：困難に対してくじけることなく、根気強く頑張ること persevere"}]}],s={bookId:t,chapterId:e,week:2,day:4,weekTitle:"第2週",dayTitle:"4日目",sectionTitle:r,sectionTitleEn:u,sections:o};export{t as bookId,e as chapterId,b as day,i as dayTitle,s as default,r as sectionTitle,u as sectionTitleEn,o as sections,n as week,c as weekTitle};
